# Costanti
# --------------------------------------------------------------------------
APP_TITLE = "EXIName"
APP_VERSION = "0.2"

TIFF_BASED_EXTENSIONS = {".tif", ".tiff", ".dng", ".nef"}
IMAGE_EXTENSIONS = {
    ".jpg", ".jpeg", ".png", ".bmp", ".gif", ".heic", ".heif", ".webp",
} | TIFF_BASED_EXTENSIONS
VIDEO_EXTENSIONS = {
    ".mp4", ".mov", ".avi", ".mkv", ".m4v", ".3gp", ".wmv",
    ".flv", ".mts", ".m2ts", ".webm",
}
MEDIA_EXTENSIONS = IMAGE_EXTENSIONS | VIDEO_EXTENSIONS

DATE_FORMAT = "%Y-%m-%d %H.%M.%S"
DATE_FORMAT_REGEX = re.compile(r"^(\d{4})-(\d{2})-(\d{2}) (\d{2})\.(\d{2})\.(\d{2})$")
MIN_VALID_YEAR = 1970          # date "segnaposto" (es. 1904) = EXIF assente

# IMG-20260825-WA0002.jpg  ->  gruppi: data (8 cifre), "WA0002", resto (estensione)
WHATSAPP_REGEX = re.compile(
    r"^(?:IMG|VID|AUD|PTT|STK|DOC)-(\d{4})(\d{2})(\d{2})-(WA\d+)(.*)$",
    re.IGNORECASE,
)

TEMP_PREFIX = "__EXIName_tmp_"


# --------------------------------------------------------------------------
# Lettura metadati
# --------------------------------------------------------------------------
def _parse_exif_string(raw) -> datetime | None:
    if not raw:
        return None
    text = str(raw).replace("\x00", "").strip()[:19]
    try:
        return datetime.strptime(text, "%Y:%m:%d %H:%M:%S")
    except ValueError:
        return None


def get_tiff_datetime(path: Path):
    """
    Lettore minimale per i formati basati su TIFF (TIFF, DNG, NEF):
    va direttamente all'Exif IFD e prende DateTimeOriginal/Digitized,
    senza dover decodificare l'immagine RAW.
    """
    try:
        with open(path, "rb") as f:
            head = f.read(8)
            if head[:4] == b"II*\x00":
                e = "<"
            elif head[:4] == b"MM\x00*":
                e = ">"
            else:
                return None

            def read_ifd(offset):
                f.seek(offset)
                count = struct.unpack(e + "H", f.read(2))[0]
                if count > 2000:
                    return {}
                data = f.read(12 * count)
                entries = {}
                for i in range(count):
                    tag, typ, cnt, val = struct.unpack(e + "HHI4s", data[i * 12:(i + 1) * 12])
                    entries[tag] = (typ, cnt, val)
                return entries

            ifd0 = read_ifd(struct.unpack(e + "I", head[4:8])[0])
            if 0x8769 not in ifd0:
                return None
            exif_ifd = read_ifd(struct.unpack(e + "I", ifd0[0x8769][2])[0])
            for tag in (36867, 36868):          # DateTimeOriginal, DateTimeDigitized
                if tag not in exif_ifd:
                    continue
                typ, cnt, val = exif_ifd[tag]
                if typ != 2:                    # ASCII
                    continue
                if cnt <= 4:
                    raw = val[:cnt]
                else:
                    f.seek(struct.unpack(e + "I", val)[0])
                    raw = f.read(cnt)
                dt = _parse_exif_string(raw.decode("ascii", "ignore"))
                if dt:
                    return dt
    except Exception:
        pass
    return None


def get_exif_datetime(path: Path):
    """
    Data di scatto REALE: solo DateTimeOriginal o DateTimeDigitized.
    Il tag generico 'DateTime' (306) NON viene usato perche' indica
    l'ultima modifica fatta da un software, non lo scatto.
    """
    if path.suffix.lower() in TIFF_BASED_EXTENSIONS:
        dt = get_tiff_datetime(path)
        if dt:
            return dt
    if not PIL_AVAILABLE:
        return None
    try:
        with Image.open(path) as img:
            exif = img.getexif()
            if not exif:
                return None
            try:
                exif_ifd = exif.get_ifd(0x8769)
            except Exception:
                return None
            for tag in (36867, 36868):
                dt = _parse_exif_string(exif_ifd.get(tag))
                if dt:
                    return dt
    except Exception:
        pass
    return None


def get_video_datetime(path: Path):
    """Data di creazione dai metadati del video (salvata in UTC -> ora locale)."""
    if not HACHOIR_AVAILABLE:
        return None
    try:
        parser = createParser(str(path))
        if not parser:
            return None
        with parser:
            metadata = extractMetadata(parser)
        if not metadata:
            return None
        for key in ("creation_date", "date_time_original", "date_time", "last_modification"):
            try:
                if metadata.has(key):
                    val = metadata.get(key)
                    if isinstance(val, datetime):
                        return val.replace(tzinfo=timezone.utc).astimezone().replace(tzinfo=None)
            except Exception:
                continue
    except Exception:
        return None
    return None


def get_mtime_datetime(path: Path) -> datetime:
    return datetime.fromtimestamp(path.stat().st_mtime)


def get_capture_datetime(path: Path):
    """(datetime, 'EXIF') se c'e' un dato reale, altrimenti (mtime, 'MTIME')."""
    ext = path.suffix.lower()
    dt = None
    if ext in IMAGE_EXTENSIONS:
        dt = get_exif_datetime(path)
    elif ext in VIDEO_EXTENSIONS:
        dt = get_video_datetime(path)
    if dt is not None and dt.year >= MIN_VALID_YEAR:
        return dt, "EXIF"
    return get_mtime_datetime(path), "MTIME"


def whatsapp_new_name(name: str):
    """IMG-20260825-WA0002.jpg -> 2026-08-25-WA0002.jpg (None se non e' WhatsApp)."""
    m = WHATSAPP_REGEX.match(name)
    if not m:
        return None
    y, mo, d, wa, rest = m.groups()
    try:
        datetime(int(y), int(mo), int(d))
    except ValueError:
        return None
    return f"{y}-{mo}-{d}-{wa.upper()}{rest}"


def open_file_with_default_app(path: Path):
    if sys.platform.startswith("win"):
        os.startfile(str(path))  # type: ignore[attr-defined]
    elif sys.platform == "darwin":
        subprocess.Popen(["open", str(path)])
    else:
        subprocess.Popen(["xdg-open", str(path)])


def natural_key(text: str):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", text)]


# --------------------------------------------------------------------------
# Nomi univoci (per cartella)
# --------------------------------------------------------------------------
def build_unique_names(rows, dt_getter):
    """
    Nome proposto per ogni riga, unico all'interno della propria cartella.
    Piu' file sullo stesso secondo (stessa estensione, stessa cartella)
    ricevono _1, _2, ... in ordine cronologico/di nome.
    """
    groups = {}
    for row in rows:
        dt = dt_getter(row)
        key = (str(row["path"].parent), dt.strftime(DATE_FORMAT), row["ext"].lower())
        groups.setdefault(key, []).append((dt, row))

    result = {}
    for (_folder, base, _ext), items in groups.items():
        items.sort(key=lambda p: (p[0], natural_key(p[1]["path"].name)))
        for idx, (_dt, row) in enumerate(items):
            suffix = "" if idx == 0 else f"_{idx}"
            result[id(row)] = f"{base}{suffix}{row['ext']}"
    return result


def find_conflicts(rows, proposed: dict):
    """
    Ritorna gli id delle righe il cui nome proposto:
      - coincide con un file gia' presente nella cartella che NON fa parte
        della rinomina, oppure
      - e' uguale al nome proposto per un'altra riga della stessa cartella.
    """
    by_folder = {}
    for row in rows:
        by_folder.setdefault(row["path"].parent, []).append(row)

    conflicts = set()
    for folder, folder_rows in by_folder.items():
        try:
            existing = {p.name.lower() for p in folder.iterdir() if p.is_file()}
        except Exception:
            existing = set()
        moving = {r["path"].name.lower() for r in folder_rows
                  if proposed[id(r)] != r["path"].name}
        seen = set()
        for row in sorted(folder_rows, key=lambda r: natural_key(r["path"].name)):
            new = proposed[id(row)]
            if new == row["path"].name:
                seen.add(new.lower())
                continue
            low = new.lower()
            if (low in existing and low not in moving) or low in seen:
                conflicts.add(id(row))
            else:
                seen.add(low)
    return conflicts


# --------------------------------------------------------------------------
# Scansione (thread separato)
# --------------------------------------------------------------------------
def collect_files(sources, recursive: bool):
    """Elenco (file, cartella_radice) da cartelle e/o file singoli, senza doppioni."""
    seen, out = set(), []

    def add(p: Path, root: Path):
        key = os.path.normcase(str(p.resolve()))
        if key in seen or p.name.startswith(TEMP_PREFIX):
            return
        seen.add(key)
        out.append((p, root))

    for src in sources:
        if src.is_file():
            add(src, src.parent)
        elif src.is_dir():
            if recursive:
                for dirpath, dirnames, filenames in os.walk(src):
                    dirnames[:] = [d for d in dirnames if not d.startswith(".")]
                    for fn in filenames:
                        add(Path(dirpath) / fn, src)
            else:
                with os.scandir(src) as it:
                    for entry in it:
                        if entry.is_file():
                            add(Path(entry.path), src)
    return out


def scan_sources(sources, recursive, q: "queue.Queue", stop: threading.Event):
    try:
        files = collect_files(sources, recursive)
    except Exception as exc:
        q.put(("error", str(exc)))
        return

    media = [(p, r) for p, r in files if p.suffix.lower() in MEDIA_EXTENSIONS]
    q.put(("total", len(media)))

    date_rows, wa_rows = [], []
    for i, (path, root) in enumerate(media, start=1):
        if stop.is_set():
            return
        try:
            dt, source = get_capture_datetime(path)
            mtime = get_mtime_datetime(path)
        except Exception:
            continue
        date_rows.append({
            "path": path, "root": root, "ext": path.suffix,
            "kind": "immagine" if path.suffix.lower() in IMAGE_EXTENSIONS else "video",
            "exif_dt": dt, "has_exif": source == "EXIF",
            "manual_dt": None, "mtime_dt": mtime,
        })
        q.put(("progress", i, len(media)))

    for path, root in files:
        new = whatsapp_new_name(path.name)
        if new:
            wa_rows.append({"path": path, "root": root, "ext": path.suffix, "new_name": new})

    q.put(("done", date_rows, wa_rows))


